  * Category B env vars:
  *   CX_DEDUP_MODE                  — "fail" | "warn" | "first-wins"
  *   CX_REPOMIX_MISSING_EXTENSION   — "fail" | "warn"
  *   CX_CONFIG_DUPLICATE_ENTRY      — "fail" | "warn" | "first-wins"
+ *   CX_ASSETS_LAYOUT               — "flat" | "deep"
  */

